1	use typst_library::diag::warning;
2	use typst_library::foundations::{Packed, Resolve};
3	use typst_library::introspection::{SplitLocator, Tag, TagElem};
4	use typst_library::layout::{
5	    Abs, BoxElem, Dir, Fr, Frame, HElem, InlineElem, InlineItem, Sizing, Spacing,
6	};
7	use typst_library::routines::Pair;
8	use typst_library::text::{
9	    LinebreakElem, SmartQuoteElem, SmartQuoter, SmartQuotes, SpaceElem, TextElem,
10	    is_default_ignorable,
11	};
12	use typst_syntax::Span;
13	use typst_utils::Numeric;
14	
15	use super::*;
16	use crate::modifiers::{FrameModifiers, FrameModify, layout_and_modify};
17	
18	// The characters by which spacing, inline content and pins are replaced in the
19	// full text.
20	const SPACING_REPLACE: &str = " "; // Space
21	const OBJ_REPLACE: &str = "\u{FFFC}"; // Object Replacement Character
22	
23	// Unicode BiDi control characters.
24	const LTR_EMBEDDING: &str = "\u{202A}";
25	const RTL_EMBEDDING: &str = "\u{202B}";
26	const POP_EMBEDDING: &str = "\u{202C}";
27	const LTR_ISOLATE: &str = "\u{2066}";
28	const POP_ISOLATE: &str = "\u{2069}";
29	
30	/// A prepared item in a inline layout.
31	#[derive(Debug)]
32	pub enum Item<'a> {
33	    /// A shaped text run with consistent style and direction.
34	    Text(ShapedText<'a>),
35	    /// Absolute spacing between other items, and whether it is weak.
36	    Absolute(Abs, bool),
37	    /// Spacing produced by paragraph geometry, such as a first-line or
38	    /// hanging indent.
39	    Indent(Abs),
40	    /// Fractional spacing between other items.
41	    Fractional(Fr, Option<(&'a Packed<BoxElem>, Locator<'a>, StyleChain<'a>)>),
42	    /// Layouted inline-level content.
43	    Frame(Frame),
44	    /// A tag.
45	    Tag(&'a Tag),
46	    /// An item that is invisible and needs to be skipped, e.g. a Unicode
47	    /// isolate.
48	    Skip(&'static str),
49	}
50	
51	impl<'a> Item<'a> {
52	    /// If this a text item, return it.
53	    pub fn text(&self) -> Option<&ShapedText<'a>> {
54	        match self {
55	            Self::Text(shaped) => Some(shaped),
56	            _ => None,
57	        }
58	    }
59	
60	    /// If this a text item, return it mutably.
61	    pub fn text_mut(&mut self) -> Option<&mut ShapedText<'a>> {
62	        match self {
63	            Self::Text(shaped) => Some(shaped),
64	            _ => None,
65	        }
66	    }
67	
68	    /// Whether this item can be skipped for the purposes of finding a leading
69	    /// or trailing item.
70	    pub fn is_skippable(&self) -> bool {
71	        match self {
72	            Self::Text(text) => text.glyphs.is_empty(),
73	            Self::Indent(_) => true,
74	            Self::Tag(_) => true,
75	            Self::Skip(_) => true,
76	            _ => false,
77	        }
78	    }
79	
80	    /// Return the textual representation of this item: Either just itself (for
81	    /// a text item) or a replacement string (for any other item).
82	    pub fn textual(&self) -> &str {
83	        match self {
84	            Self::Text(shaped) => shaped.text,
85	            Self::Absolute(_, _) | Self::Indent(_) | Self::Fractional(_, _) => {
86	                SPACING_REPLACE
87	            }
88	            Self::Frame(_) => OBJ_REPLACE,
89	            Self::Tag(_) => "",
90	            Self::Skip(s) => s,
91	        }
92	    }
93	
94	    /// The text length of the item.
95	    pub fn textual_len(&self) -> usize {
96	        self.textual().len()
97	    }
98	
99	    /// The natural layouted width of the item.
100	    pub fn natural_width(&self) -> Abs {
101	        match self {
102	            Self::Text(shaped) => shaped.width(),
103	            Self::Absolute(v, _) | Self::Indent(v) => *v,
104	            Self::Frame(frame) => frame.width(),
105	            Self::Fractional(_, _) | Self::Tag(_) => Abs::zero(),
106	            Self::Skip(_) => Abs::zero(),
107	        }
108	    }
109	}
110	
111	/// An item or not-yet shaped text. We can't shape text until we have collected
112	/// all items because only then we can compute BiDi, and we need to split shape
113	/// runs at level boundaries.
114	#[derive(Debug)]
115	pub enum Segment<'a> {
116	    /// One or multiple collapsed text children. Stores how long the segment is
117	    /// (in bytes of the full text string).
118	    Text(usize, StyleChain<'a>),
119	    /// An already prepared item.
120	    Item(Item<'a>),
121	}
122	
123	impl Segment<'_> {
124	    /// The text length of the item.
125	    pub fn textual_len(&self) -> usize {
126	        match self {
127	            Self::Text(len, _) => *len,
128	            Self::Item(item) => item.textual_len(),
129	        }
130	    }
131	}
132	
133	/// Collects all text into one string and a collection of segments that
134	/// correspond to pieces of that string. This also performs string-level
135	/// preprocessing like case transformations.
136	#[typst_macros::time]
137	pub fn collect<'a>(
138	    children: &[Pair<'a>],
139	    engine: &mut Engine<'_>,
140	    locator: &mut SplitLocator<'a>,
141	    config: &Config,
142	    region: Size,
143	) -> SourceResult<(String, Vec<Segment<'a>>, SpanMapper)> {
144	    let mut collector = Collector::new(2 + children.len());
145	    let mut quoter = SmartQuoter::new();
146	
147	    if !config.first_line_indent.is_zero() {
148	        collector.push_item(Item::Indent(config.first_line_indent));
149	        collector.spans.push(1, Span::detached());
150	    }
151	
152	    if !config.hanging_indent.is_zero() {
153	        collector.push_item(Item::Indent(-config.hanging_indent));
154	        collector.spans.push(1, Span::detached());
155	    }
156	
157	    for &(child, styles) in children {
158	        let prev_len = collector.full.len();
159	
160	        if child.is::<SpaceElem>() {
161	            collector.push_text(" ", styles);
162	        } else if let Some(elem) = child.to_packed::<TextElem>() {
163	            collector.build_text(styles, |full| {
164	                let dir = styles.resolve(TextElem::dir);
165	                if dir != config.dir {
166	                    // Insert "Explicit Directional Embedding".
167	                    match dir {
168	                        Dir::LTR => full.push_str(LTR_EMBEDDING),
169	                        Dir::RTL => full.push_str(RTL_EMBEDDING),
170	                        _ => {}
171	                    }
172	                }
173	
174	                if let Some(case) = styles.get(TextElem::case) {
175	                    full.push_str(&case.apply(&elem.text));
176	                } else {
177	                    full.push_str(&elem.text);
178	                }
179	
180	                if dir != config.dir {
181	                    // Insert "Pop Directional Formatting".
182	                    full.push_str(POP_EMBEDDING);
183	                }
184	            });
185	        } else if let Some(elem) = child.to_packed::<HElem>() {
186	            if elem.amount.is_zero() {
187	                continue;
188	            }
189	
190	            collector.push_item(match elem.amount {
191	                Spacing::Fr(fr) => Item::Fractional(fr, None),
192	                Spacing::Rel(rel) => Item::Absolute(
193	                    rel.resolve(styles).relative_to(region.x),
194	                    elem.weak.get(styles),
195	                ),
196	            });
197	        } else if let Some(elem) = child.to_packed::<LinebreakElem>() {
198	            collector.push_text(
199	                if elem.justify.get(styles) { "\u{2028}" } else { "\n" },
200	                styles,
201	            );
202	        } else if let Some(elem) = child.to_packed::<SmartQuoteElem>() {
203	            let double = elem.double.get(styles);
204	            if elem.enabled.get(styles) {
205	                let quotes = SmartQuotes::get(
206	                    elem.quotes.get_ref(styles),
207	                    styles.get(TextElem::lang),
208	                    styles.get(TextElem::region),
209	                    elem.alternative.get(styles),
210	                );
211	                let before =
212	                    collector.full.chars().rev().find(|&c| !is_default_ignorable(c));
213	                let quote = quoter.quote(before, &quotes, double);
214	                collector.push_text(quote, styles);
215	            } else {
216	                collector.push_text(SmartQuotes::fallback(double), styles);
217	            }
218	        } else if let Some(elem) = child.to_packed::<InlineElem>() {
219	            collector.push_item(Item::Skip(LTR_ISOLATE));
220	
221	            for item in elem.layout(engine, locator.next(&elem.span()), styles, region)? {
222	                match item {
223	                    InlineItem::Space(space, weak) => {
224	                        collector.push_item(Item::Absolute(space, weak));
225	                    }
226	                    InlineItem::Frame(mut frame) => {
227	                        frame.modify(&FrameModifiers::get_in(styles));
228	                        apply_shift(&engine.world, &mut frame, styles);
229	                        collector.push_item(Item::Frame(frame));
230	                    }
231	                }
232	            }
233	
234	            collector.push_item(Item::Skip(POP_ISOLATE));
235	        } else if let Some(elem) = child.to_packed::<BoxElem>() {
236	            let loc = locator.next(&elem.span());
237	            if let Sizing::Fr(v) = elem.width.get(styles) {
238	                collector.push_item(Item::Fractional(v, Some((elem, loc, styles))));
239	            } else {
240	                let mut frame = layout_and_modify(styles, |styles| {
241	                    layout_box(elem, engine, loc, styles, region)
242	                })?;
243	                apply_shift(&engine.world, &mut frame, styles);
244	                collector.push_item(Item::Frame(frame));
245	            }
246	        } else if let Some(elem) = child.to_packed::<TagElem>() {
247	            collector.push_item(Item::Tag(&elem.tag));
248	        } else {
249	            // Non-paragraph inline layout should never trigger this since it
250	            // only won't be triggered if we see any non-inline content.
251	            engine.sink.warn(warning!(
252	                child.span(),
253	                "{} may not occur inside of a paragraph and was ignored",
254	                child.func().name(),
255	            ));
256	        }
257	
258	        let len = collector.full.len() - prev_len;
259	        collector.spans.push(len, child.span());
260	    }
261	
262	    Ok((collector.full, collector.segments, collector.spans))
263	}
264	
265	/// Collects segments.
266	struct Collector<'a> {
267	    full: String,
268	    segments: Vec<Segment<'a>>,
269	    spans: SpanMapper,
270	}
271	
272	impl<'a> Collector<'a> {
273	    fn new(capacity: usize) -> Self {
274	        Self {
275	            full: String::new(),
276	            segments: Vec::with_capacity(capacity),
277	            spans: SpanMapper::new(),
278	        }
279	    }
280	
281	    fn push_text(&mut self, text: &str, styles: StyleChain<'a>) {
282	        self.build_text(styles, |full| full.push_str(text));
283	    }
284	
285	    fn build_text<F>(&mut self, styles: StyleChain<'a>, f: F)
286	    where
287	        F: FnOnce(&mut String),
288	    {
289	        let prev = self.full.len();
290	        f(&mut self.full);
291	        let segment_len = self.full.len() - prev;
292	
293	        // Merge adjacent text segments with the same styles.
294	        if let Some(Segment::Text(last_len, last_styles)) = self.segments.last_mut()
295	            && *last_styles == styles
296	        {
297	            *last_len += segment_len;
298	            return;
299	        }
300	
301	        self.segments.push(Segment::Text(segment_len, styles));
302	    }
303	
304	    fn push_item(&mut self, item: Item<'a>) {
305	        match (self.segments.last_mut(), &item) {
306	            // Merge adjacent weak spacing by taking the maximum.
307	            (
308	                Some(Segment::Item(Item::Absolute(prev_amount, true))),
309	                Item::Absolute(amount, true),
