2	use typst_library::layout::{Dir, Em};
3	use typst_library::text::TextElem;
4	use unicode_bidi::{BidiInfo, Level as BidiLevel};
5	
6	use super::*;
7	
8	/// A representation in which children are already layouted and text is already
9	/// preshaped.
10	///
11	/// In many cases, we can directly reuse these results when constructing a line.
12	/// Only when a line break falls onto a text index that is not safe-to-break per
13	/// rustybuzz, we have to reshape that portion.
14	pub struct Preparation<'a> {
15	    /// The full text.
16	    pub text: &'a str,
17	    /// Configuration for inline layout.
18	    pub config: &'a Config,
19	    /// Bidirectional text embedding levels.
20	    ///
21	    /// This is `None` if all text directions are uniform (all the base
22	    /// direction).
23	    pub bidi: Option<BidiInfo<'a>>,
24	    /// Text runs, spacing and layouted elements.
25	    pub items: Vec<(Range, Item<'a>)>,
26	    /// Maps from byte indices to item indices.
27	    pub indices: Vec<usize>,
28	    /// The span mapper.
29	    pub spans: SpanMapper,
30	}
31	
32	impl<'a> Preparation<'a> {
33	    /// Get the item that contains the given `text_offset`.
34	    pub fn get(&self, offset: usize) -> &(Range, Item<'a>) {
35	        let idx = self.indices.get(offset).copied().unwrap_or(0);
36	        &self.items[idx]
37	    }
38	
39	    /// Iterate over the items that intersect the given `sliced` range alongside
40	    /// their indices in `self.items` and their ranges in the paragraph's text.
41	    pub fn slice(
42	        &self,
43	        sliced: Range,
44	    ) -> impl Iterator<Item = (usize, &(Range, Item<'a>))> {
45	        // Usually, we don't want empty-range items at the start of the line
46	        // (because they will be part of the previous line), but for the first
47	        // line, we need to keep them.
48	        let start = match sliced.start {
49	            0 => 0,
50	            n => self.indices.get(n).copied().unwrap_or(0),
51	        };
52	        self.items
53	            .iter()
54	            .enumerate()
55	            .skip(start)
56	            .take_while(move |(_, (range, _))| {
57	                range.start < sliced.end || range.end <= sliced.end
58	            })
59	    }
60	}
61	
62	/// Performs BiDi analysis and then prepares further layout by building a
63	/// representation on which we can do line breaking without layouting each and
64	/// every line from scratch.
65	#[typst_macros::time]
66	pub fn prepare<'a>(
67	    engine: &mut Engine,
68	    config: &'a Config,
69	    text: &'a str,
70	    segments: Vec<Segment<'a>>,
71	    spans: SpanMapper,
72	) -> SourceResult<Preparation<'a>> {
73	    let default_level = match config.dir {
74	        Dir::RTL => BidiLevel::rtl(),
75	        _ => BidiLevel::ltr(),
76	    };
77	
78	    let bidi = BidiInfo::new(text, Some(default_level));
79	    let is_bidi = bidi
80	        .levels
81	        .iter()
82	        .any(|level| level.is_ltr() != default_level.is_ltr());
83	
84	    let mut cursor = 0;
85	    let mut items = Vec::with_capacity(segments.len());
86	
87	    // Shape the text to finalize the items.
88	    for segment in segments {
89	        let len = segment.textual_len();
90	        let end = cursor + len;
91	        let range = cursor..end;
92	
93	        match segment {
94	            Segment::Text(_, styles) => {
95	                shape_range(&mut items, engine, text, &bidi, range, styles);
96	            }
97	            Segment::Item(item) => items.push((range, item)),
98	        }
99	
100	        cursor = end;
101	    }
102	
103	    // Build the mapping from byte to item indices.
104	    let mut indices = Vec::with_capacity(text.len());
105	    for (i, (range, _)) in items.iter().enumerate() {
106	        indices.extend(range.clone().map(|_| i));
107	    }
108	
109	    if config.cjk_latin_spacing {
110	        add_cjk_latin_spacing(&mut items);
111	    }
112	
113	    Ok(Preparation {
114	        config,
115	        text,
116	        bidi: is_bidi.then_some(bidi),
117	        items,
118	        indices,
119	        spans,
120	    })
121	}
122	
123	/// Add some spacing between Han characters and western characters. See
124	/// Requirements for Chinese Text Layout, Section 3.2.2 Mixed Text Composition
125	/// in Horizontal Written Mode
126	fn add_cjk_latin_spacing(items: &mut [(Range, Item)]) {
127	    let mut iter = items
128	        .iter_mut()
129	        .filter(|(_, item)| !item.is_skippable())
130	        .flat_map(|(_, item)| match item {
131	            Item::Text(text) => Either::Left({
132	                // Check whether the text is normal, sub- or superscript. At
133	                // boundaries between these three, we do not want to insert
134	                // CJK-Latin-Spacing.
135	                let shift =
136	                    text.styles.get_ref(TextElem::shift_settings).map(|shift| shift.kind);
137	
138	                // Since we only call this function in [`prepare`], we can
139	                // assume that the Cow is owned, and `to_mut` can be called
140	                // without overhead.
141	                text.glyphs.to_mut().iter_mut().map(move |g| Some((g, shift)))
142	            }),
143	            _ => Either::Right(std::iter::once(None)),
144	        })
145	        .peekable();
146	
147	    let mut prev: Option<(&mut ShapedGlyph, _)> = None;
148	    while let Some(mut item) = iter.next() {
149	        if let Some((glyph, shift)) = &mut item {
150	            // Case 1: CJ followed by a Latin character
151	            if glyph.is_cj_script()
152	                && let Some(Some((next_glyph, next_shift))) = iter.peek()
153	                && next_glyph.is_letter_or_number()
154	                && *shift == *next_shift
155	            {
156	                // The spacing defaults to 1/4 em, and can be shrunk to 1/8 em.
157	                glyph.x_advance += Em::new(0.25);
158	                glyph.adjustability.shrinkability.1 += Em::new(0.125);
159	            }
160	
161	            // Case 2: Latin followed by a CJ character
162	            if glyph.is_cj_script()
163	                && let Some((prev_glyph, prev_shift)) = prev
164	                && prev_glyph.is_letter_or_number()
165	                && *shift == prev_shift
166	            {
167	                glyph.x_advance += Em::new(0.25);
168	                glyph.x_offset += Em::new(0.25);
169	                glyph.adjustability.shrinkability.0 += Em::new(0.125);
170	                prev_glyph.is_justifiable = true;
171	            }
172	        }
173	        prev = item;
174	    }
175	}
