229	    /// The amount by which the glyph's advance width is allowed to be shrunk or
230	    /// stretched to improve justification.
231	    pub fn base_adjustability(
232	        &self,
233	        style: CjkPunctStyle,
234	        limits: &JustificationLimits,
235	        stretchable: bool,
236	    ) -> Adjustability {
237	        let width = self.x_advance;
238	
239	        // Do not ever shrink away more than three quarters of the glyph. As the
240	        // width approaches zero, justification gets increasingly expensive and
241	        // if negative it may not terminate.
242	        let limited = |v: Em| v.min(width * 0.75);
243	
244	        if self.is_space() {
245	            // To a space, both the spacing and tracking limits apply, just like
246	            // `text.tracking` and `text.spacing` both apply to spaces.
247	            let max = limits.spacing().max + limits.tracking().max;
248	            let min = limits.spacing().min + limits.tracking().min;
249	            Adjustability {
250	                stretchability: (
251	                    Em::zero(),
252	                    (max - Rel::one())
253	                        .map(|length| Em::from_length(length, self.size))
254	                        .relative_to(width)
255	                        .max(Em::zero()),
256	                ),
257	                shrinkability: (
258	                    Em::zero(),
259	                    limited(
260	                        (Rel::one() - min)
261	                            .map(|length| Em::from_length(length, self.size))
262	                            .relative_to(width),
263	                    ),
264	                ),
265	            }
266	        } else if self.is_cjk_left_aligned_punctuation(style) {
267	            Adjustability {
268	                stretchability: (Em::zero(), Em::zero()),
269	                shrinkability: (Em::zero(), width / 2.0),
270	            }
271	        } else if self.is_cjk_right_aligned_punctuation() {
272	            Adjustability {
273	                stretchability: (Em::zero(), Em::zero()),
274	                shrinkability: (width / 2.0, Em::zero()),
275	            }
276	        } else if self.is_cjk_center_aligned_punctuation(style) {
277	            Adjustability {
278	                stretchability: (Em::zero(), Em::zero()),
279	                shrinkability: (width / 4.0, width / 4.0),
280	            }
281	        } else if stretchable {
282	            Adjustability {
283	                stretchability: (
284	                    Em::zero(),
285	                    Em::from_length(limits.tracking().max, self.size).max(Em::zero()),
286	                ),
287	                shrinkability: (
288	                    Em::zero(),
289	                    limited(Em::from_length(-limits.tracking().min, self.size)),
290	                ),
291	            }
292	        } else {
293	            Adjustability::default()
294	        }
295	    }
