322	    /// Build the shaped text's frame.
323	    ///
324	    /// The `justification` defines how much extra advance width each
325	    /// [justifiable glyph](ShapedGlyph::is_justifiable) will get.
326	    pub fn build(
327	        &self,
328	        engine: &Engine,
329	        spans: &SpanMapper,
330	        justification_ratio: f64,
331	        extra_justification: Abs,
332	    ) -> Frame {
333	        let (top, bottom) = self.measure(engine);
334	        let size = Size::new(self.width(), top + bottom);
335	
336	        let mut offset = Abs::zero();
337	        let mut frame = Frame::soft(size);
338	        frame.set_baseline(top);
339	
340	        let size = self.styles.resolve(TextElem::size);
341	        let shift = self.styles.resolve(TextElem::baseline);
342	        let decos = self.styles.get_cloned(TextElem::deco);
343	        let fill = self.styles.get_ref(TextElem::fill);
344	        let stroke = self.styles.resolve(TextElem::stroke);
345	        let span_offset = self.styles.get(TextElem::span_offset);
346	
347	        let mut i = 0;
348	        for ((font, y_offset, glyph_size), group) in self
349	            .glyphs
350	            .all()
351	            .group_by_key(|g| (g.font.clone(), g.y_offset, g.size))
352	        {
353	            let mut range = group[0].range.clone();
354	            for glyph in group {
355	                range.start = range.start.min(glyph.range.start);
356	                range.end = range.end.max(glyph.range.end);
357	            }
358	
359	            let pos = Point::new(offset, top + shift - y_offset.at(size));
360	            let glyphs: Vec<Glyph> = group
361	                .iter()
362	                .map(|shaped: &ShapedGlyph| {
363	                    // Whether the glyph is _not_ trimmed end-of-line
364	                    // whitespace. Trimmed whitespace has its advance width and
365	                    // offset zeroed out and is not taken into account for
366	                    // justification.
367	                    let kept = self.glyphs.kept.contains(&i);
368	
369	                    let (x_advance, x_offset) = if kept {
370	                        let adjustability_left = if justification_ratio < 0.0 {
371	                            shaped.shrinkability().0
372	                        } else {
373	                            shaped.stretchability().0
374	                        };
375	                        let adjustability_right = if justification_ratio < 0.0 {
376	                            shaped.shrinkability().1
377	                        } else {
378	                            shaped.stretchability().1
379	                        };
380	
381	                        let justification_left = adjustability_left * justification_ratio;
382	                        let mut justification_right =
383	                            adjustability_right * justification_ratio;
384	                        if shaped.is_justifiable() {
385	                            justification_right +=
386	                                Em::from_abs(extra_justification, glyph_size);
387	                        }
388	
389	                        frame.size_mut().x += justification_left.at(glyph_size)
390	                            + justification_right.at(glyph_size);
391	
392	                        (
393	                            shaped.x_advance + justification_left + justification_right,
394	                            shaped.x_offset + justification_left,
395	                        )
396	                    } else {
397	                        (Em::zero(), Em::zero())
398	                    };
399	                    i += 1;
400	
401	                    // We may not be able to reach the offset completely if
402	                    // it exceeds u16, but better to have a roughly correct
403	                    // span offset than nothing.
404	                    let mut span = spans.span_at(shaped.range.start);
405	                    span.1 = span.1.saturating_add(span_offset.saturating_as());
406	
407	                    // |<---- a Glyph ---->|
408	                    //  -->|ShapedGlyph|<--
409	                    // +---+-----------+---+
410	                    // |   |  *********|   |
411	                    // |   |  *        |   |
412	                    // |   |  *    ****|   |
413	                    // |   |  *       *|   |
414	                    // |   |  *********|   |
415	                    // +---+--+--------+---+
416	                    //   A   B     C     D
417	                    // Note A, B, D could be positive, zero, or negative.
418	                    // A: justification_left
419	                    // B: ShapedGlyph's x_offset
420	                    //    (though a small part of the glyph may go inside B)
421	                    // B+C: ShapedGlyph's x_advance
422	                    // D: justification_right
423	                    // A+B: Glyph's x_offset
424	                    // A+B+C+D: Glyph's x_advance
425	                    Glyph {
426	                        id: shaped.glyph_id,
427	                        x_advance,
428	                        x_offset,
429	                        y_advance: Em::zero(),
430	                        y_offset: Em::zero(),
431	                        range: (shaped.range.start - range.start).saturating_as()
432	                            ..(shaped.range.end - range.start).saturating_as(),
433	                        span,
434	                    }
435	                })
436	                .collect();
437	
438	            let item = TextItem {
439	                font,
440	                size: glyph_size,
441	                lang: self.lang,
442	                region: self.region,
443	                fill: fill.clone(),
444	                stroke: stroke.clone().map(|s| s.unwrap_or_default()),
445	                text: self.text[range.start - self.base..range.end - self.base].into(),
446	                glyphs,
447	            };
448	
449	            let width = item.width();
450	            if decos.is_empty() {
451	                frame.push(pos, FrameItem::Text(item));
452	            } else {
453	                // Apply line decorations.
454	                frame.push(pos, FrameItem::Text(item.clone()));
455	                for deco in &decos {
456	                    decorate(&mut frame, deco, &item, width, shift, pos);
457	                }
458	            }
459	
460	            offset += width;
461	        }
462	
463	        frame.modify_text(self.styles);
464	        frame
465	    }
