473	    /// Measure the top and bottom extent of this text.
474	    pub fn measure(&self, engine: &Engine) -> (Abs, Abs) {
475	        let mut top = Abs::zero();
476	        let mut bottom = Abs::zero();
477	
478	        let size = self.styles.resolve(TextElem::size);
479	        let top_edge = self.styles.get(TextElem::top_edge);
480	        let bottom_edge = self.styles.get(TextElem::bottom_edge);
481	
482	        // Expand top and bottom by reading the font's vertical metrics.
483	        let mut expand = |font: &FontInstance, bounds: TextEdgeBounds| {
484	            let (t, b) = font.edges(top_edge, bottom_edge, size, bounds);
485	            top.set_max(t);
486	            bottom.set_max(b);
487	        };
488	
489	        if self.glyphs.is_fully_empty() {
490	            // When there are no glyphs, we just use the vertical metrics of the
491	            // first available font.
492	            let world = engine.world;
493	            let variations = self.styles.get_cloned(TextElem::variations);
494	            if let Some(font) = families(self.styles).find_map(|family| {
495	                world
496	                    .book()
497	                    .select(family.as_str(), self.variant)
498	                    .and_then(|id| world.font(id))
499	                    .map(|font| font.instantiate(self.variant, size, &variations))
500	            }) {
501	                expand(&font, TextEdgeBounds::Zero);
502	            }
503	        } else {
504	            for g in self.glyphs.iter() {
505	                expand(&g.font, TextEdgeBounds::Glyph(g.glyph_id));
506	            }
507	        }
508	
509	        (top, bottom)
510	    }
